from amazon_textract import AmazonTextract

client = AmazonTextract()

def extract_invoice_data(document_path):
    response = client.analyze_document(
        Document={'Bytes': open(document_path, 'rb').read()},
        FeatureTypes=['TABLES', 'FORMS']
    )

    vendor = None
    date = None
    total = None
    line_items = []

    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if block['Text'] == 'Vendor':
                vendor = next(b['Text'] for b in response['Blocks'] if b['BlockType'] == 'VALUE' and b['Relationships'][0]['Ids'][0] == block['Id'])
            elif block['Text'] == 'Date':
                date = next(b['Text'] for b in response['Blocks'] if b['BlockType'] == 'VALUE' and b['Relationships'][0]['Ids'][0] == block['Id'])
            elif block['Text'] == 'Total':
                total = next(b['Text'] for b in response['Blocks'] if b['BlockType'] == 'VALUE' and b['Relationships'][0]['Ids'][0] == block['Id'])
        elif block['BlockType'] == 'TABLE':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                        if child_block['BlockType'] == 'CELL':
                            line_items.append({
                                'item': child_block['Text'],
                                'quantity': next((b['Text'] for b in response['Blocks'] if b['Id'] in child_block['Relationships'][0]['Ids'] and b['BlockType'] == 'VALUE'), None),
                                'price': next((b['Text'] for b in response['Blocks'] if b['Id'] in child_block['Relationships'][1]['Ids'] and b['BlockType'] == 'VALUE'), None)
                            })

    return {
       'vendor': vendor,
        'date': date,
        'total': total,
        'line_items': line_items
    }
